mapper.sql:
SELECT s.id AS source_id,s.provider_code,e.content_version_id,e.id AS base_evaluation_id,e.rule_release_id,
    row_number() OVER (ORDER BY s.collected_at,s.id) AS ordinal,attachment_backfill_input_hash(s.id) AS input_hash
FROM announcement_source_snapshots s JOIN announcement_source_classification_evaluations e ON e.source_id=s.id AND e.is_current
WHERE s.data_purpose_code='PRODUCTION' AND s.provider_code IN

    CASE WHEN #{provider}='GOV24' THEN 'GOV24_PUBLIC_SERVICE' ELSE #{provider} END

AND s.collected_at>=#{scope.collectedFrom} AND s.collected_at<#{scope.collectedBefore}
AND s.application_end_date>=#{scope.deadlineFrom}
AND s.application_end_date<=#{scope.deadlineThrough}
AND

mapper.select:
-- 전체 최초 분할을 고정 순서로 읽는다. 완전 삭제된 분할도 숨기지 않는다.
SELECT  FROM announcement_attachment_backfill_segments s
WHERE s.run_id=#{runId} ORDER BY s.segment_no LIMIT #{size} OFFSET #{offset}

-- 고정 item만 조회한다. 변경·제외된 입력은 false로 표시하고 새 후보로 대체하지 않는다.
SELECT ordinal,source_id,content_version_id,base_evaluation_id,rule_release_id,provider_code,input_hash,
    coalesce(input_hash=attachment_backfill_input_hash(source_id),false) AS current_input_matches
FROM announcement_attachment_backfill_items WHERE run_id=#{runId} AND segment_no=#{segmentNo}
ORDER BY ordinal LIMIT #{size} OFFSET #{offset}
